<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class RoomCategory extends Model{protected $fillable=['name','color','daily_price','weekly_price','monthly_price'];protected $casts=['daily_price'=>'decimal:2','weekly_price'=>'decimal:2','monthly_price'=>'decimal:2'];public function rooms(){return $this->hasMany(Room::class);}public function photos(){return $this->hasMany(MediaFile::class)->where('kind','CATEGORY')->orderBy('position')->orderBy('id');}}
